CREATE TRIGGER _cf_WAKE_delete AFTER DELETE ON _cf_ALARM BEGIN
               UPDATE _cf_WAKE SET sequence=sequence+1,at_ms=NULL WHERE scope=OLD.scope;
             END

CREATE TRIGGER _cf_WAKE_insert AFTER INSERT ON _cf_ALARM BEGIN
               UPDATE _cf_WAKE SET sequence=sequence+1,at_ms=NEW.at_ms WHERE scope=NEW.scope;
             END

CREATE TRIGGER _cf_WAKE_update AFTER UPDATE OF at_ms,generation ON _cf_ALARM BEGIN
               UPDATE _cf_WAKE SET sequence=sequence+1,at_ms=NEW.at_ms WHERE scope=NEW.scope;
             END
